findings.literal:
/* Concrete chain, not var(--font-body): the @theme inline font tokens no
   * longer emit :root aliases. --font-dm-sans sits on <html> via next/font,
   * so this resolves here. */

@theme inline {
  --font-display: var(--font-bebas-neue), sans-serif;
  --font-body: var(--font-dm-sans), sans-serif;
  --font-mono: var(--font-dm-mono), monospace;
  --font-outfit: var(--font-outfit-sans), sans-serif;
  --font-rd: var(--font-archivo), system-ui, sans-serif;
}

